function stageRows(fixtureId, rows) {
  return rows.map((row, index) => ({
    fixture_id: fixtureId,
    stage_order: index + 1,
    stage_version: row.stage_version ?? 0,
    duration_minutes: row.duration_minutes ?? null,
    updated_at: row.updated_at || row.completed_at || row.started_at || row.assigned_at || "2026-05-01T08:00:00Z",
    ...row,
  }));
}

function attemptRows(fixtureId, rows) {
  return rows.map((row, index) => ({
    fixture_id: fixtureId,
    attempt_no: row.attempt_no ?? index + 1,
    duration_minutes: row.duration_minutes ?? null,
    updated_at: row.updated_at || row.approved_at || row.completed_at || row.started_at || "2026-05-01T08:00:00Z",
    ...row,
  }));
}

